package gen

import (
	"regexp"
	"strconv"
	"strings"
)

// HeaderPrefix starts the first line of every generated file. The writer
// uses it to tell generated files from handwritten ones, and the repository
// SPDX check skips files that start with it; the
// repository tests import it rather than repeating the literal. Both the
// current header and the older one that carried a momo version start with it.
const HeaderPrefix = "// Code generated by momo "

// Header returns the single generated-file header line. It matches Go's
// convention `^// Code generated .* DO NOT EDIT\.$`; every emitter uses it.
// It carries the format number, which decides compatibility, and no momo
// release version, so upgrading momo does not rewrite generated files.
func Header() string {
	return HeaderPrefix + "(format " + strconv.Itoa(FormatVersion) + "). DO NOT EDIT."
}

// headerRe accepts the current header and the older form with a version
// between "momo" and "(format N)".
var headerRe = regexp.MustCompile(`^// Code generated by momo (?:\S+ )?\(format ([0-9]+)\)\. DO NOT EDIT\.$`)

// ParseHeader reports whether line is a momo generated-file header, in the
// current form or the older form that carried a version, and returns its
// format number. A trailing newline or CRLF on line is ignored.
func ParseHeader(line string) (format int, ok bool) {
	m := headerRe.FindStringSubmatch(strings.TrimRight(line, "\r\n"))
	if m == nil {
		return 0, false
	}
	n, err := strconv.Atoi(m[1])
	if err != nil {
		return 0, false
	}
	return n, true
}
